SELECT MONTH(c.signup_date) AS signup_month, CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, SUM(CASE WHEN o.status = 'COMPLETED' THEN o.amount ELSE 0 END) AS completed_amount FROM orders o INNER JOIN customers c ON o.customer_id = c.id LEFT OUTER JOIN stores s ON o.store_id = s.id GROUP BY MONTH(c.signup_date), CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END HAVING SUM(CASE WHEN o.status = 'COMPLETED' THEN o.amount ELSE 0 END) > 20 ORDER BY signup_cohort;
